import{_ as d,l as s,o as p,b as n,q as l,d as t,f as i,m as a,j as c}from"./chunks/framework.Tf23FRXt.js";const g="/assets/f35410b5737415c85d9beae44b4eedf980bf21.DJCxUJdT.jpg",m="/images/icons/060570.png",u="/assets/cfbf5694cefe3d4076a13bb9a0ad48584bed86.Dt64eb5-.jpg",b="/assets/e8d215cfd8b89fa8784afd19ab03334191ab8c.CxLn-hJo.jpg",f="/assets/bee436efb4acf0180609e1012d413f435f6c56.B0ltelfu.jpg",v="/assets/hist1.t0ZhNzoK.jpg",_="/assets/hist2.CThrCg6W.jpg",h="/assets/hist3.DBHLu1r-.jpg",q=JSON.parse('{"title":"道具与背包","description":"","frontmatter":{},"headers":[{"level":2,"title":"背包扩展","slug":"背包扩展","link":"#背包扩展","children":[]},{"level":2,"title":"市场交易","slug":"市场交易","link":"#市场交易","children":[{"level":3,"title":"价格查询","slug":"价格查询","link":"#价格查询","children":[]}]},{"level":2,"title":"物品获取方式查询","slug":"物品获取方式查询","link":"#物品获取方式查询","children":[]}],"relativePath":"basic/item.htm.md","filePath":"basic/item.md","lastUpdated":1791101830000}'),k={name:"basic/item.htm.md"};function x(T,e,C,S,w,N){const r=s("quest"),o=s("SegmentText");return p(),n("div",null,[e[7]||(e[7]=l('<h1 id="道具与背包" tabindex="-1">道具与背包</h1><p>玩家获得的道具会放在背包中（默认快捷键 <code>I</code> ），背包默认有 140 个格子，可以在<a href="/basic/config.htm">角色设置</a>中将背包展开为单页布局。</p><p>背包中还有一个单独的 “任务道具与水晶” 分页，水晶是<a href="/topic/craft.htm">生产制作</a>时所需的媒触，任务道具则是一些只能在任务中使用的物品，物品名通常是橙黄色的，如果你在背包中找不到某样道具，也可以在任务道具分栏里找找看。</p><p>装备有单独的存储空间，名为<mark>兵装库</mark>（默认快捷键 <code>Ctrl+I</code> ），按装备部位分栏，如果兵装库满了，获得的装备会自动进入背包（如果背包也满了，则会提示无法获得）。可以在角色设置中，将获得装备时的默认收纳改为背包。</p><blockquote><p>关于装备道具的介绍请参阅<a href="/basic/equip.htm">装备介绍</a>。</p></blockquote><h2 id="背包扩展" tabindex="-1">背包扩展</h2>',6)),t("p",null,[e[0]||(e[0]=i("在完成陆行鸟相关任务",-1)),a(r,{name:"可靠的搭档",type:"plus"}),e[1]||(e[1]=i("后，会获得",-1)),e[2]||(e[2]=t("mark",null,"陆行鸟鞍囊",-1)),e[3]||(e[3]=i("（俗称鸟包，默认快捷键 ",-1)),e[4]||(e[4]=t("code",null,"Ctrl+Shift+I",-1)),e[5]||(e[5]=i(" ），鸟包只能在副本以外的地区打开，算是随身携带的扩展包。",-1))]),e[8]||(e[8]=t("p",null,[i("在"),t("a",{href:"https://actff1.web.sdo.com/project/141028dgf/index.html",target:"_blank",rel:"noreferrer"},"后勤补给站"),i("可以购买神典石服务，能游戏内开启第二个陆行鸟鞍囊，但需要保持续费（15 元 / 月）才能一直使用。")],-1)),e[9]||(e[9]=t("p",null,[i("完成 17 级主线之后，可以在市场雇佣雇员，作为仓库和销售的渠道，关于雇员的具体介绍请"),t("a",{href:"/advanced/retainer.htm"},"查看本页"),i("。")],-1)),a(o,{className:"green"},{default:c(()=>[...e[6]||(e[6]=[t("h3",{id:"道具检索",tabindex:"-1"},"道具检索",-1),t("p",null,[i("在消息栏中输入 "),t("code",null,"/道具检索 关键字"),i(" ，就可以在装备中的物品、背包、陆行鸟鞍囊、兵装库、雇员物品栏、收藏柜、投影台中检索拥有该关键字的物品。在检索结果列表中"),t("i",{class:"xiv mouse-right-button"}),i("右键道具名字，并选择"),t("mark",null,"查看持有情况"),i("，就能看到这件物品目前的位置了。")],-1),t("p",null,"如果长时间未使用雇员、鸟包、幻化台，道具检索会无法检索到这些地方的物品（提示 “该搜索结果可能无法反映当前最新的情报。”），建议在开始检索之前打开一次雇员、鸟包。",-1)])]),_:1}),e[10]||(e[10]=l('<h2 id="市场交易" tabindex="-1">市场交易</h2><p>绝大部分道具都可以在市场上交易，不可在市场交易的物品，会在其信息栏最下方标识<mark>不可在市场出售</mark>。</p><div class="guide cols2"><div class="guide col"><p><img src="'+g+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>玩家可以在各个主城、住宅区设置的市场布告板上使用市场功能。</p><p>地图上标记有<img src="'+m+'" class="no-zoom sm-icon">板子图标的位置就是市场布告板。</p><p>※所有市场布告板上的出售列表是共通的。<br> ※出售物品需要通过雇员进行，记得去雇佣雇员哦。</p><blockquote><p><a href="/advanced/retainer.htm">雇员介绍</a></p></blockquote></div></div><p>像是装备这种数量太多，不容易找到想要物品的时候，可以使用分类搜索，限制装备等级、适合职业等条件，筛选搜索结果。</p><div class="guide cols2"><div class="guide col figcap grow"><p><img src="'+u+'" alt="" loading="lazy"></p><p><strong>想找主 / 副手</strong><br> 选择分类，输入装备等级，点击下方的搜索按钮！<br> ※ 排在越靠上的装备性能越好</p></div><div class="guide col figcap grow"><p><img src="'+b+'" alt="" loading="lazy"></p><p><strong>想找装备 / 饰品</strong><br> 选择分类，输入装备等级和职业，点击下方的搜索按钮！<br> ※ 排在越靠上的装备性能越好</p></div></div><div class="guide cols2"><div class="guide col"><p><img src="'+f+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>如果只记得想要物品的部分名称，推荐使用 “部分一致” 搜索功能筛选物品！</p><p>在输入关键字的输入框上面，勾选 “部分一致”，就可以扩大搜索范围，按 <code>回车</code> 键或者按下方的搜索按钮都可以。</p><p>※搜索结果显示在右边。</p></div></div><p>从市场上购买道具需要支付 2% 的手续费，如果想要购买昂贵的物品，也可以选择面对面交易（注意面对面交易的单笔金额上限为 100 万<i class="xiv gil"></i>）。装备还可以从住宅区房屋的模特上整套购买。</p><h3 id="价格查询" tabindex="-1">价格查询</h3><p>市场中物品的售价是由冒险者自由决定的，因此相同的商品也会有价格差异。这个时候只要打开 “交易履历”，就可以比较现在的售价和过去的成交价格。出售商品时，如果不好定价，也可以参考交易履历来决定。一定要好好利用这个功能。</p><div class="guide base cols3"><div class="guide col"><img src="'+v+'" width="250px"><p>打开市场布告板，找到想要的物品。</p></div><div class="guide col"><img src="'+_+'" width="250px"><p>点击 “查看市场情况” 右上角的 “显示履历”，<br>会弹出选中物品的交易履历。</p></div><div class="guide col"><img src="'+h+'" width="250px"><p>在交易履历里，可以看到过去成交的单价、数量、<br>购买时间以及购买人的名字等交易信息。</p></div></div><h2 id="物品获取方式查询" tabindex="-1">物品获取方式查询</h2><p>可以从 NPC 购买的道具，会在道具信息上显示 NPC 售价，除此以外玩家很难在游戏中找到一件物品的来源和价格。</p><p>此时可以通过第三方玩家网站，查询物品获取方式及价格：</p><blockquote><ul><li><a href="https://ff14.huijiwiki.com/wiki/ItemSearch" target="_blank" rel="noreferrer">FF14 灰机维基物品检索器</a></li><li><a href="https://garlandtools.cn/db/" target="_blank" rel="noreferrer">加兰德数据库</a></li><li><a href="https://universalis.app/" target="_blank" rel="noreferrer">Universalis 布告板价格统计站</a></li></ul></blockquote>',14))])}const I=d(k,[["render",x]]);export{q as __pageData,I as default};
